package noppes.npcs.client.gui.player.cinematic;

import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.OpenGlHelper;
import net.minecraft.client.renderer.Tessellator;
import net.minecraft.util.ResourceLocation;
import noppes.npcs.constants.EnumOptionType;
import noppes.npcs.constants.EnumRoleType;
import noppes.npcs.controllers.data.DialogOption;
import org.lwjgl.opengl.GL11;

/**
 * Cells of textures/gui/dialog_icons.png, generated by tools/gen_dialog_icons.py.
 * The index is the cell: keep it in step with ICONS in the generator.
 */
public final class DialogIcons {
    public static final int TALK = 0;
    public static final int QUEST = 1;
    public static final int QUIT = 2;
    public static final int COMMAND = 3;
    public static final int ACCEPT = 4;
    public static final int ROLE_TRADER = 5;
    public static final int ROLE_BANK = 6;
    public static final int ROLE_FOLLOWER = 7;
    public static final int ROLE_TRANSPORTER = 8;
    public static final int ROLE_POSTMAN = 9;
    public static final int ROLE_COMPANION = 10;
    public static final int ROLE_MOUNT = 11;
    public static final int ROLE_NONE = 12;

    public static final int SIZE = 9;
    private static final int COLS = 7;
    private static final float SHEET = 64f;
    private static final ResourceLocation TEXTURE = new ResourceLocation("customnpcs", "textures/gui/dialog_icons.png");

    public static final int COLOR_TALK = 0xFFEDEDED;
    public static final int COLOR_QUEST = 0xFFFFC94A;
    public static final int COLOR_QUIT = 0xFFFF6A5E;
    public static final int COLOR_COMMAND = 0xFF7FE3FF;
    public static final int COLOR_ACCEPT = 0xFF7CFF8A;
    public static final int COLOR_ROLE = 0xFFFFD65A;

    private DialogIcons() {
    }

    public static int iconFor(DialogOption option, EnumRoleType role) {
        switch (option.optionType) {
            case QuitOption:
                return QUIT;
            case CommandBlock:
                return COMMAND;
            case RoleOption:
                return roleIcon(role);
            default:
                return option.targetHasQuest ? QUEST : TALK;
        }
    }

    public static int colorFor(int icon) {
        switch (icon) {
            case QUEST:
                return COLOR_QUEST;
            case QUIT:
                return COLOR_QUIT;
            case COMMAND:
                return COLOR_COMMAND;
            case ACCEPT:
                return COLOR_ACCEPT;
            case TALK:
                return COLOR_TALK;
            default:
                return COLOR_ROLE;
        }
    }

    public static int roleIcon(EnumRoleType role) {
        if (role == null)
            return ROLE_NONE;
        switch (role) {
            case Trader:
                return ROLE_TRADER;
            case Bank:
                return ROLE_BANK;
            case Follower:
                return ROLE_FOLLOWER;
            case Transporter:
                return ROLE_TRANSPORTER;
            case Postman:
                return ROLE_POSTMAN;
            case Companion:
                return ROLE_COMPANION;
            case Mount:
                return ROLE_MOUNT;
            default:
                return ROLE_NONE;
        }
    }

    /**
     * Draws one icon tinted with an ARGB color at its native size of 9 units.
     */
    public static void draw(int icon, float x, float y, int color, float alpha) {
        Minecraft.getMinecraft().getTextureManager().bindTexture(TEXTURE);
        GL11.glEnable(GL11.GL_BLEND);
        GL11.glEnable(GL11.GL_TEXTURE_2D);
        OpenGlHelper.glBlendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA, 1, 0);
        float a = ((color >>> 24) & 255) / 255f * alpha;
        GL11.glColor4f(((color >> 16) & 255) / 255f, ((color >> 8) & 255) / 255f, (color & 255) / 255f, a);
        float u0 = (icon % COLS) * SIZE / SHEET, v0 = (icon / COLS) * SIZE / SHEET;
        float u1 = u0 + SIZE / SHEET, v1 = v0 + SIZE / SHEET;
        Tessellator t = Tessellator.instance;
        t.startDrawingQuads();
        t.addVertexWithUV(x, y + SIZE, 0, u0, v1);
        t.addVertexWithUV(x + SIZE, y + SIZE, 0, u1, v1);
        t.addVertexWithUV(x + SIZE, y, 0, u1, v0);
        t.addVertexWithUV(x, y, 0, u0, v0);
        t.draw();
        GL11.glColor4f(1, 1, 1, 1);
    }

    /**
     * True for the option types that keep the conversation going.
     */
    public static boolean continues(DialogOption option) {
        return option.optionType == EnumOptionType.DialogOption;
    }
}
